//! Contract of Scheda: the messages and service traits of
//! `api/scheda/v1/*.proto`, generated by `bazel run //api:generate`.
//!
//! Everything is reachable as `scheda_api::v1`: the messages (by
//! `protoc-gen-buffa`, with serde), their [`Validate`](protovalidate_buffa::Validate)
//! impls (by `protoc-gen-protovalidate-buffa`), and the traits of the
//! services and ports (by `protoc-gen-protocontract-buffa`). The async forms
//! and the `Offload` / `Blocking` bridges exist with the `tokio` feature.

/// The messages, as `protoc-gen-buffa` writes them
/// (`buffa_module=crate::proto`).
#[rustfmt::skip]
#[path = "gen/buffa/mod.rs"]
mod proto;

/// The `Validate` impls of the messages, as `protoc-gen-protovalidate-buffa`
/// writes them (`packaging=false`), one file per proto.
#[rustfmt::skip]
#[allow(unused_imports)]
mod validators {
    use crate::proto::scheda::v1::*;

    include!("gen/buffa/scheda.v1.collection.validate.rs");
    include!("gen/buffa/scheda.v1.document.validate.rs");
    include!("gen/buffa/scheda.v1.error.validate.rs");
    include!("gen/buffa/scheda.v1.index.validate.rs");
    include!("gen/buffa/scheda.v1.marker.validate.rs");
    include!("gen/buffa/scheda.v1.mirror.validate.rs");
    include!("gen/buffa/scheda.v1.options.validate.rs");
    include!("gen/buffa/scheda.v1.ports.validate.rs");
    include!("gen/buffa/scheda.v1.query.validate.rs");
    include!("gen/buffa/scheda.v1.scheda.validate.rs");
    include!("gen/buffa/scheda.v1.vault.validate.rs");
}

/// The traits of the services, as `protoc-gen-protocontract-buffa` writes
/// them (`file_per_package`).
#[rustfmt::skip]
mod traits {
    include!("gen/contract/scheda.v1.rs");
}

/// Package `scheda.v1`: messages, enums, and service traits.
pub mod v1 {
    pub use crate::proto::scheda::v1::*;
    pub use crate::traits::*;
}
